using System.Collections.Generic;
public class GUPMatchingEntityRebate 
    implements Microsoft.Dynamics.Commerce.Runtime.Services.PricingEngine.IMatchingEntityNonGenericProvider
{
    public str id;
    public Microsoft.Dynamics.Commerce.Runtime.DataModel.PricingMatchingDimension dimension;
    public int pricingPriority;
    public CLRObject pricingMatchingRules;

}

Method.Source:
public void init(TAMRebateTable rebateTable, TAMRebateDate rebateDate, int priority = 0)
{
    this.id = int642Str(rebateDate.RecId);
    this.dimension = GUPMatchingEntityHelper::initMatchingDimensionFromInventDim(rebateTable.InventDimId);
    this.pricingPriority = priority;
    this.pricingMatchingRules = GUPMatchingEntityHelper::initMatchingRules(rebateTable.PricingRuleHeader, rebateTable.PricingRuleLine);
}
